package com.narada.android

import com.narada.android.connection.*
import com.narada.connection.*
import java.util.UUID
import kotlinx.coroutines.runBlocking
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test

/** Real JNI + sealed aggregate with explicit software test keys; no AndroidKeyStore claim. */
class ProtectedChatJournalTest {
    private class Fixture {
        val anchor=TestAnchor();val keys=TestKeys();val blob=TestBlob();val crypto=VodozemacOlm()
        val peer=TransferTestData.peer().copy(remotePermissions=Permissions(chat=true),remoteOperations=listOf("health","permissions","files.v1","transfers.v1","chat.olm.v1","attachments.age.v1","sync.v1"))
        fun open()=ProtectedConnectionsRepository(anchor,keys,blob)
        suspend fun setup():ChatEngine {val r=open();r.initialize();r.mutate{it.copy(enabled=true,peers=listOf(peer),preferredPeer=peer.id)};return ChatEngine(r,crypto).also{it.enablePeer(peer.id,true)}}
    }
    private fun failure(code:String?=null,body:suspend ()->Unit)=runBlocking{try{body();org.junit.Assert.fail("Expected failure")}catch(e:ConnectionFailure){if(code!=null)assertEquals(code,e.code)}}
    @Test fun accountDraftAndOutboxAreSealedNotMetadataOrDebugStrings()=runBlocking<Unit>{val f=Fixture();val e=f.setup();e.saveDraft(f.peer.id,"PRIVATE_DRAFT_SENTINEL");val old=f.open().read()!!;val encrypted=f.blob.bytes!!.toString(Charsets.ISO_8859_1);assertFalse(encrypted.contains("PRIVATE_DRAFT_SENTINEL"));assertFalse(encrypted.contains(old.chat!!.account));assertFalse(old.toString().contains(old.chat!!.curve));val m=e.queue(f.peer.id,UUID.randomUUID().toString(),"PRIVATE_TEXT_SENTINEL");assertFalse(f.blob.bytes!!.toString(Charsets.ISO_8859_1).contains(m.text));assertEquals(m,f.open().read()!!.chat!!.message(m.id));assertTrue(f.open().read()!!.chat!!.drafts.isEmpty());assertEquals(1,f.keys.creations)}
    @Test fun payloadThreeUpgradesWithoutChangingTransportStoreOrExistingJournal()=runBlocking<Unit>{val f=Fixture();val r=f.open();val original=r.initialize();val old=original.copy(version=3);val json=Wire.json.encodeToJsonElement(old).jsonObject;f.blob.write(f.keys.seal(old.storeId,JsonObject(json.filterKeys{it!="chat"}).toString().toByteArray()));assertEquals(3,f.open().read()!!.version);val next=f.open().mutate{it.copy(enabled=true)};assertEquals(6,next.version);assertEquals(old.deviceId,next.deviceId);assertEquals(old.storeId,next.storeId);assertEquals(old.certificate,next.certificate);assertNull(next.chat);assertEquals(1,f.keys.creations)}
    @Test fun establishedOlmEnrollmentCannotBeDropped()=runBlocking<Unit>{val f=Fixture();f.setup();val old=f.blob.bytes!!.clone();failure("CRYPTO_STATE_INVALID"){f.open().mutate{it.copy(chat=null)}};assertArrayEquals(old,f.blob.bytes);assertEquals(1,f.keys.creations)}
    @Test fun establishedCryptoIdentityCannotBeReplaced()=runBlocking<Unit>{val f=Fixture();f.setup();val replacement=f.crypto.create();val old=f.blob.bytes!!.clone();failure("CRYPTO_STATE_INVALID"){f.open().mutate{it.copy(chat=it.chat!!.copy(account=replacement.account,curve=replacement.curve,ed=replacement.ed))}};assertArrayEquals(old,f.blob.bytes)}
    @Test fun immutableOutgoingBodyCannotBeChangedEvenWithARecomputedHash()=runBlocking<Unit>{val f=Fixture();val e=f.setup();val m=e.queue(f.peer.id,UUID.randomUUID().toString(),"unchanged");failure("CHAT_STATE_INVALID"){f.open().mutate{d->d.copy(chat=d.chat!!.replace(m.copy(text="changed",requestHash=chatRequestHash(d.deviceId,m.peerId,m.pairingAttempt,m.id,"changed"))))}};assertEquals(m,f.open().read()!!.chat!!.message(m.id))}
    @Test fun unknownOutcomeAndHistoryCannotBeSilentlyEvicted()=runBlocking<Unit>{val f=Fixture();val e=f.setup();e.queue(f.peer.id,UUID.randomUUID().toString(),"retain");failure("CHAT_STATE_INVALID"){f.open().mutate{it.copy(chat=it.chat!!.copy(messages=emptyList()))}};assertEquals(1,f.open().read()!!.chat!!.messages.size)}
    @Test fun nativePickleCorruptionIsDetectedOnReopenNotOnlyOnSend()=runBlocking<Unit>{val f=Fixture();f.setup();val d=f.open().read()!!;f.blob.write(f.keys.seal(d.storeId,Wire.encode(d.copy(chat=d.chat!!.copy(account="{}")),Wire.MAX_STORE)));val damaged=f.blob.bytes!!.clone();failure("TRUST_STORE_INVALID"){f.open().read()};failure("TRUST_STORE_INVALID"){f.open().initialize()};assertArrayEquals(damaged,f.blob.bytes);assertEquals(1,f.keys.creations)}
    @Test fun failedQueueWriteNeverClearsTheSavedDraftOrCreatesAnOutbox()=runBlocking<Unit>{val f=Fixture();val e=f.setup();e.saveDraft(f.peer.id,"saved draft");val old=f.blob.bytes!!.clone();f.blob.failWrite=true;failure("STORAGE_UNAVAILABLE"){e.queue(f.peer.id,UUID.randomUUID().toString(),"saved draft")};f.blob.failWrite=false;assertArrayEquals(old,f.blob.bytes);assertEquals("saved draft",f.open().read()!!.chat!!.drafts.single().text);assertTrue(f.open().read()!!.chat!!.messages.isEmpty())}
    @Test fun revocationPreservesAlreadyReceivedHistoryAndDraft()=runBlocking<Unit>{val f=Fixture();val e=f.setup();e.saveDraft(f.peer.id,"retained private draft");val before=f.open().read()!!.chat;f.open().mutate{d->d.copy(peers=listOf(d.peer(f.peer.id).copy(status=TrustStatus.REVOKED,remotePermissions=Permissions(),remoteOperations=emptyList(),localEpoch=2)),preferredPeer=null)};assertEquals(before,f.open().read()!!.chat)}
    @Test fun boundedTextHistoryRoundTripsWithTheLargerStrictAggregateLimit()=runBlocking<Unit>{val f=Fixture();val e=f.setup();repeat(32){e.queue(f.peer.id,UUID.randomUUID().toString(),"é".repeat(2048))};val d=f.open().read()!!;assertEquals(32,d.chat!!.messages.size);assertTrue(Wire.encode(d,Wire.MAX_STORE).size<Wire.MAX_STORE);failure("CHAT_HISTORY_FULL"){e.queue(f.peer.id,UUID.randomUUID().toString(),"overflow")};assertEquals(d,f.open().read())}
    @Test fun aDamagedPersistedSessionCannotPassAProtectedReopen()=runBlocking<Unit>{val f=Fixture();f.setup();val d=f.open().read()!!;val c=d.chat!!;val b=c.bindings.single();val remote=f.crypto.bundle(f.crypto.create().account,b.peerId,d.deviceId).bundle;val encrypted=f.crypto.encrypt(c.account,b.ours,remote,null,ChatBody(message_id=UUID.randomUUID().toString(),sender=d.deviceId,recipient=b.peerId,text="native session fixture"));val valid=f.open().mutate{it.copy(chat=c.replace(b.copy(remote=remote,sessions=listOf(encrypted.session))))};val corrupt=valid.copy(chat=valid.chat!!.replace(valid.chat!!.bindings.single().copy(sessions=listOf(encrypted.session.copy(pickle="{}")))));f.blob.write(f.keys.seal(d.storeId,Wire.encode(corrupt,Wire.MAX_STORE)));val bytes=f.blob.bytes!!.clone();failure("TRUST_STORE_INVALID"){f.open().read()};assertArrayEquals(bytes,f.blob.bytes);assertEquals(1,f.keys.creations)}

}
